import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('initial state and start', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned' });
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('nobody')).ok, false);
});

test('complete both', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed' });
});

test('cancel races a completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  // Abort goes to both workers: task0's report is still in flight
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.equal(aborts.length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('cancel after a report sends one abort', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  await h.cancel();
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('cancel before assign arrives', async () => {
  const h = await createHost();
  await h.start(); await h.cancel();
  // deliver aborts first: ignored by idle workers, then Assigns make them busy
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelling', task0: 'assigned', task1: 'assigned' });
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed' });
});

