import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, retried0 = false, retried1 = false) => ({ status, task0, task1, retried0, retried1 });

test('initial state and start', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('nobody')).ok, false);
});

test('complete both', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliver((await h.inFlight())[0].id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', true));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action]), [['run', 'worker0', 'Assign']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', true));
});

test('retry then complete', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workDone('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, true));
});

test('a failure while cancelling is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

test('cancel races a completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.inFlight()).filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('cancel races a retry', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();  // retry Assign delivered, worker0 busy
  await h.cancel(); await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'cancelled', 'cancelled', true));
});

test('cancel before assign arrives', async () => {
  const h = await createHost();
  await h.start(); await h.cancel();
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed'));
});

