import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, retried0 = false, retried1 = false) => ({ status, task0, task1, retried0, retried1 });

input.content:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, { retried0 = false, retried1 = false, processed = 0 } = {}) => ({ status, task0, task1, retried0, retried1, processed });

test('initial state and start', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('nobody', 1)).ok, false);
});

test('items must be 1 or 2', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  for (const bad of [0, 3, -1, 1.5]) assert.equal((await h.workDone('worker0', bad)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.inFlight(), []);
});

test('complete both, counting items', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', { processed: 2 }));
  await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 3 }));
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  const [r] = await h.inFlight();
  assert.deepEqual(r.data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliver(r.id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', { retried0: true }));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action]), [['run', 'worker0', 'Assign']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', { retried0: true, processed: 2 }));
});

test('retry then complete', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workDone('worker1', 2); await h.workDone('worker0', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { retried1: true, processed: 4 }));
});

test('a failure while cancelling is recorded', async () => {
