  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', { processed: 2 }));
});

test('a completion after a timeout is ignored and not counted', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker1', 2);
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed'));
  await h.workDone('worker0', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', { processed: 1 }));
});

test('a late failure report after a timeout is not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed'));
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  await h.taskTimeout(0); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'failed'));
});

test('timeout while cancelling', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
  assert.equal((await h.taskTimeout(0)).ok, false);
});

test('cancel before assign arrives', async () => {
  const h = await createHost();
  await h.start(); await h.cancel();
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  await h.workFailed('worker0'); await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', { processed: 1 }));
});
